import type { IKeyValueStore } from "../storage/KeyValueStore.ts";
import { logger } from "../logger.ts";

export interface SecureKeyEntry {
    keyId: string;
    keyData: string;
    algorithm: string;
    createdAt: number;
    expiresAt?: number;
}

export interface SecureKeyOptions {
    encryptionKey?: string;
    keyLifetime?: number;
}

export class SecureKeyManager {
    private keys: Map<string, SecureKeyEntry> = new Map();
    private encryptionKey: string;
    private keyLifetime: number;

    public constructor(
        private store: IKeyValueStore,
        options: SecureKeyOptions = {},
    ) {
        this.encryptionKey = options.encryptionKey ?? this.generateEncryptionKey();
        this.keyLifetime = options.keyLifetime ?? 86400000;

        this.loadKeys();
    }

    public async storeKey(keyId: string, keyData: string, algorithm: string, ttl?: number): Promise<void> {
        const effectiveTtl = ttl ?? this.keyLifetime;
        const entry: SecureKeyEntry = {
            keyId,
            keyData: this.encrypt(keyData),
            algorithm,
            createdAt: Date.now(),
            expiresAt: effectiveTtl ? Date.now() + effectiveTtl : undefined,
        };

        this.keys.set(keyId, entry);
        await this.saveKey(keyId, entry);

        logger.info(`Secure key stored: ${keyId}`);
    }

    public async getKey(keyId: string): Promise<string | null> {
        const entry = this.keys.get(keyId);

        if (!entry) {
            return null;
        }

        if (entry.expiresAt && Date.now() > entry.expiresAt) {
            await this.deleteKey(keyId);
            return null;
        }

        return this.decrypt(entry.keyData);
    }

    public async deleteKey(keyId: string): Promise<void> {
        this.keys.delete(keyId);
        await this.store.deleteItem(`secure_key_${keyId}`);

        logger.info(`Secure key deleted: ${keyId}`);
    }

    public async listKeys(algorithm?: string): Promise<SecureKeyEntry[]> {
        const entries = Array.from(this.keys.values());

        if (algorithm) {
            return entries.filter((e) => e.algorithm === algorithm);
        }

        return entries;
    }

    public async rotateKey(keyId: string, newKeyData: string): Promise<void> {
        const entry = this.keys.get(keyId);

        if (!entry) {
            throw new Error(`Key not found: ${keyId}`);
        }

        entry.keyData = this.encrypt(newKeyData);
        entry.createdAt = Date.now();

        this.keys.set(keyId, entry);
        await this.saveKey(keyId, entry);

        logger.info(`Secure key rotated: ${keyId}`);
    }

    public async cleanupExpiredKeys(): Promise<number> {
        const now = Date.now();
        const expiredKeys: string[] = [];

        for (const [keyId, entry] of this.keys.entries()) {
            if (entry.expiresAt && now > entry.expiresAt) {
                expiredKeys.push(keyId);
            }
        }

        for (const keyId of expiredKeys) {
            await this.deleteKey(keyId);
        }

        if (expiredKeys.length > 0) {
            logger.info(`Cleaned up ${expiredKeys.length} expired keys`);
        }

        return expiredKeys.length;
    }

    public async clearAllKeys(): Promise<void> {
        const keyIds = Array.from(this.keys.keys());

        for (const keyId of keyIds) {
            await this.deleteKey(keyId);
        }

        logger.info("All secure keys cleared");
    }

    public getKeyCount(): number {
        return this.keys.size;
    }

    public hasKey(keyId: string): boolean {
        const entry = this.keys.get(keyId);

        if (!entry) {
            return false;
        }

        if (entry.expiresAt && Date.now() > entry.expiresAt) {
            return false;
        }

        return true;
    }

    private encrypt(data: string): string {
        const combined = this.encryptionKey + data;
        let hash = 0;

        for (let i = 0; i < combined.length; i++) {
            const char = combined.charCodeAt(i);
            hash = (hash << 5) - hash + char;
            hash = hash & hash;
        }

        return btoa(hash.toString(16) + ":" + data);
    }

    private decrypt(encrypted: string): string {
        try {
            const decoded = atob(encrypted);
            const separatorIndex = decoded.indexOf(":");

            if (separatorIndex === -1) {
                return decoded;
            }

            return decoded.substring(separatorIndex + 1);
        } catch {
            return encrypted;
        }
    }

    private generateEncryptionKey(): string {
        const timestamp = Date.now().toString(36);
        const random = Math.random().toString(36).substring(2);
        return timestamp + random;
    }

    private async saveKey(keyId: string, entry: SecureKeyEntry): Promise<void> {
        await this.store.setItem(`secure_key_${keyId}`, entry);
    }

    private async loadKeys(): Promise<void> {
        try {
            const allKeys = await this.listStoredKeys();

            for (const keyId of allKeys) {
                const entry = await this.store.getItem<SecureKeyEntry>(`secure_key_${keyId}`);

                if (entry) {
                    if (entry.expiresAt && Date.now() > entry.expiresAt) {
                        await this.deleteKey(keyId);
                    } else {
                        this.keys.set(keyId, entry);
                    }
                }
            }

            logger.info(`Loaded ${this.keys.size} secure keys`);
        } catch (error) {
            logger.warn("Failed to load secure keys:", error);
        }
    }

    private async listStoredKeys(): Promise<string[]> {
        const prefix = "secure_key_";

        try {
            const storeKeys = await this.store.getItem<string[]>(`${prefix}list`);
            if (storeKeys) {
                return storeKeys;
            }
        } catch {}

        return [];
    }
}
